import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    columns = next(reader, None)
    if columns is None:
        return {"columns": [], "rows": []}

    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows = list(reader)
    width = max([len(columns)] + [len(row) for row in rows])

    existing = set(columns)
    index = 1
    while len(columns) < width:
        name = "extra_column_{}".format(index)
        index += 1
        if name not in existing:
            columns.append(name)
            existing.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
